-- ============================================================================
-- DEPENDENCIAS EXTERNAS - DATOS DE PRUEBA (de OTROS modulos)
-- ============================================================================
-- Datos minimos de Nomina, Compras e Inventarios para poder probar TODAS las
-- vistas de Cuentas por Pagar que dependen de ellos:
--   * Caja Chica .................. sucursales y empleados (responsable)
--   * Contrasenas de Pago ......... empleados (empleado que autoriza)
--   * Facturas Proveedor .......... proveedores (selector + validacion)
--   * Lineas de factura ........... articulos (ID articulo, opcional)
--
-- Son DATOS DE PRUEBA, no los reales: cuando Nomina / Compras / Inventarios
-- se integren, este archivo se deja de ejecutar y se usan los datos de ellos
-- (ver README.md de esta carpeta).
--
-- RE-EJECUTABLE: cada fila se inserta solo si no existe (por su codigo, NIT o
-- nombre). Correrlo dos veces no duplica nada.
-- Requiere: 01_SETUP_DEPENDENCIAS.sql ya ejecutado.
-- Los seeds de Cuentas por Pagar (RUN_ALL_SEEDS.sql) buscan estos registros
-- por su CODIGO / NIT, nunca por ID.
-- ============================================================================

SET DEFINE OFF

-- ----------------------------------------------------------------------------
-- NOMINA 1/4: Departamentos (los empleados de prueba usan 'Administración y Finanzas')
-- ----------------------------------------------------------------------------
INSERT INTO NOM_DEPARTAMENTO (NOMBRE)
SELECT 'Administración y Finanzas'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM NOM_DEPARTAMENTO WHERE NOMBRE = 'Administración y Finanzas');

INSERT INTO NOM_DEPARTAMENTO (NOMBRE)
SELECT 'Operaciones y Sucursales'
