-- ----------------------------------------------------------------------------
-- COMPRAS: Proveedores (Facturas Proveedor los busca por NIT)
--   El ultimo esta INACTIVO a proposito: no debe aparecer en el selector.
-- ----------------------------------------------------------------------------
MERGE INTO PROVEEDOR d
USING (
    SELECT '1234567-8' NIT, 'Papelería y Suministros El Estudiante, S.A.' RAZON_SOCIAL, 'El Estudiante' NOMBRE_COMERCIAL,
           '7a. Avenida 12-45 Zona 1, Guatemala' DIRECCION, '2232-1100' TELEFONO, 'ventas@elestudiante.com.gt' EMAIL,
           30 DIAS_CREDITO, 'A' CALIFICACION, '012-345678-9' CUENTA_BANCARIA, 'Banco Industrial' BANCO, 'A' ESTADO FROM DUAL UNION ALL
    SELECT '2345678-9', 'Distribuidora de Papel Térmico GT, S.A.', 'PapelTerm GT',
           'Calzada San Juan 15-20 Zona 7, Guatemala', '2440-2200', 'pedidos@papeltermgt.com', 15, 'A', '044-112233-0', 'Banco G&T Continental', 'A' FROM DUAL UNION ALL
    SELECT '3456789-0', 'Servicios de Limpieza Integral, S.A.', 'Limpieza Integral',
           '18 Calle 5-30 Zona 10, Guatemala', '2366-3300', 'contacto@limpiezaintegral.gt', 30, 'B', '301-998877-1', 'Banrural', 'A' FROM DUAL UNION ALL
    SELECT '4567890-1', 'Consultores en Auditoría Informática', 'AudiTI Consultores',
           '6a. Avenida 9-18 Zona 9, Guatemala', '2331-4400', 'info@auditi.gt', 45, 'A', '055-667788-2', 'Banco Agromercantil (BAM)', 'A' FROM DUAL UNION ALL
    SELECT '5678901-2', 'Tecnología y Almacenamiento, S.A.', 'TecnoStore',
           'Boulevard Liberación 6-31 Zona 9, Guatemala', '2385-5500', 'ventas@tecnostore.com.gt', 60, 'A', '012-554433-3', 'Banco Industrial', 'A' FROM DUAL UNION ALL
    SELECT '6789012-3', 'Software Contable de Guatemala, S.A.', 'ContaSoft',
           '12 Calle 1-25 Zona 10, Edificio Géminis', '2299-6600', 'licencias@contasoft.gt', 30, 'A', '044-221100-4', 'Banco G&T Continental', 'A' FROM DUAL UNION ALL
    SELECT '7890123-4', 'Transportes y Logística Rápida, S.A.', 'TransRápida',
           'Km 17.5 Carretera al Pacífico, Villa Nueva', '6630-7700', 'operaciones@transrapida.gt', 15, 'B', '301-445566-5', 'Banrural', 'A' FROM DUAL UNION ALL
    SELECT '8901234-5', 'Proveedor Inactivo de Prueba, S.A.', 'Inactivo',
           'Sin dirección', '0000-0000', NULL, 0, 'C', NULL, NULL, 'I' FROM DUAL
) s
ON (d.NIT = s.NIT)
WHEN NOT MATCHED THEN
    INSERT (NIT, RAZON_SOCIAL, NOMBRE_COMERCIAL, DIRECCION, TELEFONO, EMAIL, DIAS_CREDITO, CALIFICACION, CUENTA_BANCARIA, BANCO, ESTADO)
    VALUES (s.NIT, s.RAZON_SOCIAL, s.NOMBRE_COMERCIAL, s.DIRECCION, s.TELEFONO, s.EMAIL, s.DIAS_CREDITO, s.CALIFICACION, s.CUENTA_BANCARIA, s.BANCO, s.ESTADO);

COMMIT;

-- ----------------------------------------------------------------------------
-- INVENTARIOS: Categorias y articulos (lineas de factura los buscan por CODIGO)
-- ----------------------------------------------------------------------------
MERGE INTO CATEGORIA_ARTICULO d
USING (
    SELECT 'Suministros de Oficina' NOMBRE FROM DUAL UNION ALL
    SELECT 'Equipo de Cómputo' FROM DUAL UNION ALL
    SELECT 'Software y Licencias' FROM DUAL UNION ALL
    SELECT 'Insumos de Punto de Venta' FROM DUAL
) s
ON (d.NOMBRE = s.NOMBRE)
WHEN NOT MATCHED THEN INSERT (NOMBRE) VALUES (s.NOMBRE);

MERGE INTO ARTICULO d
USING (
    SELECT 'ART-2001' CODIGO, 'Resma de papel bond carta' NOMBRE, 'Suministros de Oficina' CATEGORIA,
           'Paquete' UNIDAD_MEDIDA, 'MATERIAL_USO_INTERNO' TIPO_ARTICULO, 150 COSTO FROM DUAL UNION ALL
    SELECT 'ART-2003', 'Bobina de papel térmico 80mm', 'Insumos de Punto de Venta', 'Rollo', 'MATERIAL_USO_INTERNO', 100 FROM DUAL UNION ALL
    SELECT 'ART-2006', 'Servidor de almacenamiento NAS 16TB', 'Equipo de Cómputo', 'Unidad', 'ACTIVO_FIJO', 4000 FROM DUAL UNION ALL
    SELECT 'ART-2007', 'Licencia anual de software contable', 'Software y Licencias', 'Unidad', 'MATERIAL_USO_INTERNO', 1400 FROM DUAL UNION ALL
    SELECT 'ART-2009', 'Tóner para impresora láser', 'Suministros de Oficina', 'Unidad', 'MATERIAL_USO_INTERNO', 450 FROM DUAL
) s
ON (d.CODIGO = s.CODIGO)
WHEN NOT MATCHED THEN
    INSERT (CODIGO, NOMBRE, ID_CATEGORIA, UNIDAD_MEDIDA, TIPO_ARTICULO, COSTO_PROMEDIO, ESTADO)
    VALUES (s.CODIGO, s.NOMBRE, (SELECT MIN(ID_CATEGORIA) FROM CATEGORIA_ARTICULO WHERE NOMBRE = s.CATEGORIA),
            s.UNIDAD_MEDIDA, s.TIPO_ARTICULO, s.COSTO, 'A');

COMMIT;

